SHAPES={'inbox':'<path d="M4 13l2-7h12l2 7v5H4z"/><path d="M4 13h5l1 2h4l1-2h5"/>','clock':'<circle cx="12" cy="12" r="8"/><path d="M12 8v4l3 2"/>','cal':'<rect x="4" y="5" width="16" height="15" rx="2"/><path d="M4 10h16M9 3v4M15 3v4"/>','doc':'<path d="M7 3h7l4 4v14H7z"/><path d="M14 3v4h4"/>','kan':'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M10 4v16M15 4v10"/>','users':'<circle cx="9" cy="9" r="3"/><path d="M3 19c0-3 3-5 6-5s6 2 6 5"/><circle cx="17" cy="8" r="2.4"/>','list':'<path d="M9 6h11M9 12h11M9 18h11M4 6h1M4 12h1M4 18h1"/>','arrow':'<path d="M5 12h14M13 6l6 6-6 6"/>','bot':'<rect x="5" y="8" width="14" height="11" rx="3"/><path d="M12 4v4M9 13h.01M15 13h.01"/>','plug':'<path d="M9 3v5M15 3v5M7 8h10v4a5 5 0 0 1-10 0z"/><path d="M12 17v4"/>','hook':'<circle cx="8" cy="16" r="3"/><circle cx="16" cy="16" r="3"/><circle cx="12" cy="7" r="3"/><path d="M12 10v3"/>','chart':'<path d="M5 20V10M11 20V4M17 20v-8"/>','gear':'<circle cx="12" cy="12" r="3"/><path d="M12 3v3M12 18v3M3 12h3M18 12h3M5.6 5.6l2.1 2.1M16.3 16.3l2.1 2.1M18.4 5.6l-2.1 2.1M7.7 16.3l-2.1 2.1"/>','book':'<path d="M5 4h10a4 4 0 0 1 4 4v12H9a4 4 0 0 1-4-4z"/>','chev':'<path d="M6 9l6 6 6-6"/>','search':'<circle cx="11" cy="11" r="6"/><path d="M20 20l-4-4"/>','bell':'<path d="M6 17V11a6 6 0 0 1 12 0v6l2 2H4z"/><path d="M10 21h4"/>','sun':'<circle cx="12" cy="12" r="4"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3"/>','chat':'<path d="M4 5h16v11H9l-5 4z"/>','smile':'<circle cx="12" cy="12" r="8"/><path d="M9 14c1 1.5 5 1.5 6 0M9.5 10h.01M14.5 10h.01"/>','clip':'<path d="M8 12l6-6a3 3 0 0 1 4 4l-8 8a5 5 0 0 1-7-7l7-7"/>','mic':'<rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3"/>','send':'<path d="M4 12l16-8-6 16-3-7z"/>','carleft':'<path d="M14 7l-5 5 5 5M10 7l-5 5 5 5"/>'}
def ic(n): return ICON % SHAPES[n]
def nav_item(label,icon,active=False,extra=''):
    cls="relative flex items-center gap-3 rounded-md px-3 py-1 text-sm transition-colors "+("bg-accent text-accent-foreground" if active else "text-muted-foreground hover:bg-accent/50 hover:text-foreground")
    cur=' aria-current="page"' if active else ''
    return f'<li><a href="#"{cur} class="{cls}">{ic(icon)}<span class="truncate">{label}</span>{extra}</a></li>'
def group(label,items):
    return f'''<div class="space-y-1"><h2><button type="button" aria-expanded="true" class="flex w-full items-center justify-between rounded-md px-3 py-1 text-xs font-medium text-muted-foreground transition-colors hover:bg-accent/40 hover:text-foreground">{label}<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" class="shrink-0 text-text-subtle"><path d="M6 9l6 6 6-6"/></svg></button></h2><ul class="space-y-1">{''.join(items)}</ul></div>'''
count=lambda n:f'<span class="ml-auto inline-flex h-[18px] min-w-[18px] items-center justify-center rounded-full bg-accent px-1.5 text-[10px] font-semibold text-accent-foreground">{n}</span>'
sidebar=f'''<aside class="sticky top-[var(--faixas-de-cima,0px)] z-30 flex h-[calc(100dvh-var(--faixas-de-cima,0px))] shrink-0 flex-col border-r bg-card transition-[width] duration-base w-60">
<div class="flex h-14 items-center border-b px-4 justify-start"><span class="min-w-0 truncate font-semibold tracking-tight">Sales e Associados</span><div class="ml-auto shrink-0 pl-2"><button type="button" class="flex w-full items-center gap-2 rounded-md px-3 py-2 text-xs text-muted-foreground hover:bg-accent/50 justify-center px-2">{ic('carleft')}</button></div></div>
<nav class="flex-1 space-y-2 overflow-y-auto px-2 py-1" aria-label="Navegação principal">
{group('Atendimento',[nav_item('Inbox','inbox',True,count(7)),nav_item('Radar','clock'),nav_item('Agenda','cal'),nav_item('Respostas rápidas','doc')])}
{group('CRM',[nav_item('Funis','kan'),nav_item('Contatos','users'),nav_item('Tarefas','list'),nav_item('Ver tudo em CRM','arrow')])}
{group('Agente de IA',[nav_item('Agentes','bot'),nav_item('Follow-ups','arrow'),nav_item('Casos','doc'),nav_item('Ver tudo em IA','arrow')])}
{group('Canais',[nav_item('Conexões','plug'),nav_item('Webhooks','hook')])}
{group('Análise',[nav_item('Desempenho','chart')])}
</nav>
<div class="border-t px-2 py-1"><a class="flex items-center gap-3 rounded-md px-3 py-1 text-sm text-muted-foreground" href="#">{ic('gear')}<span>Configurações</span></a><a class="flex items-center gap-3 rounded-md px-3 py-1 text-sm text-muted-foreground" href="#">{ic('book')}<span>Ajuda</span></a><div class="px-3 pt-1 text-[10px] text-muted-foreground">Versão ainda não confirmada</div></div>
</aside>'''
topbar=f'''<header class="sticky top-[var(--faixas-de-cima,0px)] z-20 flex h-14 items-center justify-between gap-2 border-b bg-background/95 px-3 backdrop-blur md:gap-4 md:px-6"><div class="flex min-w-0 items-center gap-2"></div><div class="flex min-w-0 flex-1 justify-center md:max-w-md"><button class="flex h-9 w-full items-center gap-2 rounded-md border bg-card px-3 text-sm text-muted-foreground">{ic('search')} Buscar… <span class="ml-auto rounded bg-muted px-1.5 text-[10px]">⌘K</span></button></div><div class="flex shrink-0 items-center gap-2">{ic('bell')}<span class="text-xs font-semibold">PT</span>{ic('sun')}<span class="flex h-8 w-8 items-center justify-center rounded-full bg-muted text-xs font-semibold">ED</span></div></header>'''
def av(ini): return f'<span class="relative flex shrink-0 overflow-hidden rounded-full h-10 w-10"><span class="flex h-full w-full items-center justify-center rounded-full bg-surface-elevated text-xs font-medium text-text-muted">{ini}</span></span>'
def conv(nome,msg,hora,ini,sel=False,unread=0,tags=(),fila=None):
    wrap="relative flex w-full items-start border-b border-border/70"+(" bg-accent-soft" if sel else "")
    btn="group relative flex min-w-0 flex-1 items-start gap-3 px-3 py-2.5 text-left transition-colors hover:bg-surface-elevated"+(" bg-accent-soft hover:bg-accent-soft" if sel else "")
    bar='<span class="absolute inset-y-0 left-0 w-0.5 bg-accent" aria-hidden="true"></span>' if sel else ''
    un=f'<span class="inline-flex h-[18px] min-w-[18px] shrink-0 items-center justify-center rounded-full bg-accent px-1.5 text-[10px] font-semibold tabular-nums text-accent-foreground">{unread}</span>' if unread else ''
    tg=''.join(f'<span class="inline-flex items-center rounded-md border px-1.5 h-4 text-[10px] text-text-muted">{t}</span>' for t in tags)
    tgw=f'<div class="mt-1.5 flex flex-wrap items-center gap-1">{tg}</div>' if tags else ''
    fl=f'<div class="mb-1 flex items-center gap-1.5"><span class="inline-flex h-4 min-w-4 items-center justify-center rounded-full bg-accent-soft px-1 text-[10px] font-medium text-accent">{fila}º</span><span class="text-[11px] text-text-muted">Aguardando há 3 minutos</span></div>' if fila else ''
    return f'''<div class="{wrap}"><button type="button" data-conversation-id="x" aria-current="{'true' if sel else 'false'}" class="{btn}">{bar}<div class="relative shrink-0">{av(ini)}<span class="absolute -bottom-0.5 -left-0.5 h-3 w-3 rounded-full border-2 border-background bg-success" role="img"></span><span class="absolute -bottom-1 -right-1 h-5 w-5 rounded-full bg-success ring-2 ring-background"></span></div><div class="min-w-0 flex-1">{fl}<div class="flex items-baseline justify-between gap-2"><span class="flex min-w-0 items-center gap-1.5"><span class="truncate text-sm {'font-semibold' if unread else 'font-medium'} text-text">{nome}</span></span><span class="shrink-0 text-[11px] tabular-nums text-text-subtle">{hora}</span></div><div class="mt-0.5 flex items-center justify-between gap-2"><p class="min-w-0 truncate text-[13px] {'text-text' if (unread or sel) else 'text-text-muted'}">{msg}</p>{un}</div>{tgw}</div></button></div>'''
tabs=''.join(f'<button role="tab" data-state="{"active" if i==0 else "inactive"}" class="inline-flex items-center justify-center whitespace-nowrap shrink-0 gap-1 rounded-none border-b-2 border-transparent px-0 pb-2 pt-1 text-xs font-medium text-text-muted data-[state=active]:border-accent data-[state=active]:bg-transparent data-[state=active]:text-text data-[state=active]:shadow-none">{t}</button>' for i,t in enumerate(['Automático','Fila','Minhas','Todas','Fechadas','Arquivadas']))
lista=f'''<div class="h-full min-h-0 flex-col border-r border-border md:flex flex"><div class="px-3 pt-3"><button class="inline-flex w-full items-center justify-center gap-2 rounded-md border bg-background px-4 py-2 text-sm font-medium">{ic('chat')} Iniciar conversa</button></div>
<div class="border-b border-border bg-background"><div class="space-y-2 px-3 pt-3 pb-2"><div class="flex items-center gap-2"><div class="relative min-w-0 flex-1"><input class="flex w-full border px-3 py-2 text-sm h-9 rounded-full border-transparent bg-surface-elevated pl-9 shadow-none" placeholder="Buscar por nome, telefone ou última mensagem…" aria-label="Buscar conversas"></div><button class="h-9 shrink-0 rounded-full border px-3 text-xs font-medium border-border bg-transparent text-text-muted">Não lidos</button><button class="h-9 shrink-0 rounded-full border px-3 text-xs font-medium border-border bg-transparent text-text-muted">Grupos</button></div>
<div class="flex gap-2"><button class="h-8 min-w-0 flex-1 truncate rounded-full border border-transparent bg-surface-elevated px-3 text-left text-xs shadow-none">Todas as tags</button><button class="h-8 min-w-0 flex-1 truncate rounded-full border border-transparent bg-surface-elevated px-3 text-left text-xs shadow-none">Todos os atendentes</button></div></div>
<div dir="ltr" class="px-3"><div class="flex items-center gap-1"><span class="w-4 shrink-0"></span><div role="tablist" class="inline-flex items-center max-w-full overflow-x-auto h-auto min-w-0 flex-1 flex-wrap justify-between gap-x-1 gap-y-2 rounded-none bg-transparent p-0 text-muted-foreground">{tabs}</div><span class="w-4 shrink-0"></span></div></div></div>
<div class="min-h-0 flex-1 overflow-y-auto">
{conv('Lucas Almeida','João: Oi! Estou enfrentando dificuldade com…','há 2 min','LA',False,0,(),1)}
{conv('Isabela Ribeiro','Isso parece incrível! Eu geralmente fico assistindo séries.','há 2 min','IR',True,0,('Label',))}
{conv('André Souza','João: Olá, preciso de ajuda com um pedido','há 2 min','AS',False,0,('vendas',))}
{conv('Larissa Gomes','Obrigada pelo atendimento!','há 2 min','LG',False,0,())}
{conv('Sofia Lima','João: Preciso de ajuda com um problema no','há 2 min','SL',False,2,('urgente','bug'))}
{conv('João Silva','Posso enviar o documento amanhã?','há 2 min','JS',False,3,())}
</div></div>'''
def bubble(txt,out,hora):
    cls="relative max-w-[75%] min-w-0 text-sm rounded-2xl px-3 py-2 shadow-sm "+("rounded-br-sm bg-primary text-primary-foreground" if out else "rounded-bl-sm bg-muted text-foreground")
    row="group flex w-full min-w-0 items-center gap-1 px-4 py-1 "+("justify-end" if out else "justify-start")
    return f'<div class="{row}"><div data-testid="message-bubble" class="{cls}"><p class="whitespace-pre-wrap wrap-anywhere leading-snug">{txt}</p><div class="mt-1 text-[10px] opacity-70">{hora}</div></div></div>'
conversa=f'''<div class="h-full min-h-0 min-w-0 flex-col md:flex group/conversa flex"><div class="flex flex-wrap items-center justify-between gap-2 border-b border-border bg-background px-3 py-2 md:gap-3 md:px-4 md:py-3"><div class="min-w-0"><div class="flex min-w-0 items-center gap-1.5"><h2 class="min-w-0 truncate text-sm font-semibold">Isabela Ribeiro</h2></div><p class="mt-0.5 text-xs text-muted-foreground">+55 44 99999-9999</p></div><button class="rounded-md border px-3 py-1 text-xs">Resolver</button></div>
<div class="min-h-0 flex-1 overflow-hidden"><div data-testid="chat-thread" class="relative flex h-full min-h-0 min-w-0 flex-col"><div class="min-h-0 min-w-0 flex-1 overflow-y-auto overscroll-contain py-2"><div class="space-y-1"><div class="sticky top-0 z-10 flex justify-center py-1"><span class="rounded-full bg-background/80 px-2.5 py-0.5 text-[11px] font-medium text-muted-foreground backdrop-blur">Hoje</span></div>
{bubble('Oi! Gostaria de saber mais sobre o plano para o meu escritório.',False,'13:50')}
{bubble('Claro! Posso te explicar tudo agora. Qual o tamanho da equipe?',True,'13:51 ✓✓')}
{bubble('Somos 6 advogados e 2 estagiários.',False,'13:52')}
{bubble('Perfeito. Vou te enviar a proposta com a automação dos avisos e o atendimento com IA.',True,'13:52 ✓✓')}
</div></div></div></div>
<div data-testid="composer" class="relative border-t border-border bg-background px-3 py-2"><div class="mb-1.5 flex gap-1"><button class="min-h-11 rounded-full px-3 py-1 text-xs font-medium transition-colors lg:min-h-0 lg:px-2.5 bg-accent text-accent-foreground">Responder</button><button class="min-h-11 rounded-full px-3 py-1 text-xs font-medium lg:min-h-0 lg:px-2.5 text-muted-foreground hover:bg-muted">Nota interna</button></div><div class="flex items-end gap-2"><span class="text-muted-foreground">{ic('clip')}</span><span class="text-muted-foreground">{ic('smile')}</span><textarea aria-label="Mensagem" class="max-h-40 min-h-11 flex-1 resize-none rounded-md border border-input bg-background px-3 py-2 text-base md:text-sm lg:min-h-9 placeholder:text-muted-foreground" placeholder="Escreva sua resposta…"></textarea><span class="text-muted-foreground">{ic('mic')}</span><button aria-label="Enviar" class="inline-flex shrink-0 items-center justify-center rounded-md bg-primary text-primary-foreground h-9 w-9">{ic('send')}</button></div></div></div>'''
ficha='''<div class="hidden h-full min-h-0 min-w-0 xl:block"><div class="p-4 text-sm"><div class="mb-3 text-muted-foreground">Recolher</div><div class="font-semibold">Isabela Ribeiro</div><div class="text-muted-foreground text-xs">isabela.ribeiro@gmail.com</div></div></div>'''
def pagina(tema):
    return f'''<!doctype html><html lang="pt-BR" data-theme="{tema}"><head><meta charset="utf-8"><link rel="stylesheet" href="app.css"><link rel="stylesheet" href="tema-sales.css"></head>
<body class="min-h-dvh bg-bg font-sans text-text antialiased"><div class="flex min-h-[calc(100dvh-var(--faixas-de-cima,0px))] w-full bg-background"><div class="hidden md:block" style="display:block">{sidebar}</div><div class="flex min-h-[calc(100dvh-var(--faixas-de-cima,0px))] min-w-0 flex-1 flex-col">{topbar}<main class="flex-1 overflow-auto p-4 pb-area-segura sm:p-6"><div data-realtime-status="open" class="grid relative h-[calc(100dvh-var(--faixas-de-cima,0px)-3.5rem-var(--space-6)-max(var(--space-6),var(--rodape-ocupado,0px)))] w-full" style="grid-template-columns:300px 1fr 340px">{lista}{conversa}{ficha}</div></main></div></div></body></html>'''
for t in ('light','dark'): open(f'inbox-{t}.html','w').write(pagina(t))
